n into a comprehensive contract sewing company.", "founded_year": "1977", "employee_count": "", "cage_code": "", "min_order": "No minimum order quantity", "export_compliance": [], "languages": [], "social_links": ["http://www.commercialapparel.com", "http://www.picthegift.com"], "ownership_tags": []}'::jsonb, updated_at=now() WHERE slug='commercial-apparel-inc' AND approved AND profile IS NULL;
UPDATE companies SET description='Commercial Equipment Service Inc. has operated from Wilmington, Delaware since its founding in 1984. The company provides commercial refrigeration, HVAC, and restaurant equipment services across the region, including the nearby communities of Edgemoor and Elsmere.

